window.BARALHOS = window.BARALHOS || {};
window.BARALHOS['fr'] = {"versao":1,"idioma":"fr","curso":"fr-en","audiencia":"en","leva":"59b0e5ee","total":181,"cards":[{"idioma":"fr","id":"fr-b001","tipo":"frase","fr":"Bonjour !","aceitasFr":["Bonjour.","Bonjour, madame.","Bonjour, monsieur."],"en":"Hello!","aceitasEn":["hello","good morning","good afternoon","good day"],"distratoresEn":["Good night!","See you tomorrow!","Welcome!","Good luck!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It works from morning until evening: good morning and good afternoon in one word. In France, saying «Bonjour» as you walk into a shop is close to mandatory.","requerTodas":[],"v":"4c50d50d"},{"idioma":"fr","id":"fr-b002","tipo":"frase","fr":"Bonsoir !","aceitasFr":["Bonsoir.","Bonsoir, madame.","Bonsoir, monsieur."],"en":"Good evening!","aceitasEn":["good evening","evening"],"distratoresEn":["Good morning!","Good afternoon!","See you tomorrow!","Have a good trip!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The greeting when you arrive in the evening. When someone goes to bed, French says «Bonne nuit» instead.","requerTodas":[],"v":"49b42210"},{"idioma":"fr","id":"fr-b003","tipo":"frase","fr":"Salut !","aceitasFr":["Salut.","Coucou !"],"en":"Hi!","aceitasEn":["hi","hey","hiya"],"distratoresEn":["Thanks!","Careful!","Congratulations!","Help!"],"nivel":"A1","tags":["primeiros passos","social","gíria"],"notaEn":"The casual hello among friends and colleagues; with strangers, use «Bonjour». It also works as a casual bye. The final «t» is silent.","requerTodas":[],"v":"123d5ee1"},{"idioma":"fr","id":"fr-b004","tipo":"frase","fr":"Au revoir !","aceitasFr":["Au revoir.","Au revoir, madame.","Au revoir, monsieur."],"en":"Goodbye!","aceitasEn":["goodbye","good bye","bye","bye bye"],"distratoresEn":["Welcome!","Thank you!","Congratulations!","Cheers!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The goodbye that works with anyone, at any time. Literally «until seeing again». «Au» sounds like «oh».","requerTodas":[],"v":"8d6af516"},{"idioma":"fr","id":"fr-b005","tipo":"frase","fr":"Merci !","aceitasFr":["Merci.","Merci bien !"],"en":"Thank you!","aceitasEn":["thank you","thanks"],"distratoresEn":["Please!","You're welcome!","Sorry!","Congratulations!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The stress falls at the end: «mehr-SEE», with the throaty French «r».","requerTodas":[],"v":"349d0e6c"},{"idioma":"fr","id":"fr-b006","tipo":"frase","fr":"Merci beaucoup !","aceitasFr":["Merci beaucoup.","Merci mille fois !"],"en":"Thank you very much!","aceitasEn":["thank you very much","thank you so much","thanks a lot","thanks so much","many thanks"],"distratoresEn":["Nice to meet you!","Very well done!","Of course, go ahead!","Everything's fine here!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Beaucoup» means a lot, and it goes after: «merci beaucoup», never «beaucoup merci». Say «boh-KOO».","requerTodas":[],"v":"419a49d1"},{"idioma":"fr","id":"fr-b007","tipo":"frase","fr":"De rien !","aceitasFr":["De rien.","Je vous en prie.","Je t'en prie.","Avec plaisir !"],"en":"You're welcome!","aceitasEn":["you are welcome","youre welcome","no problem","dont mention it","not at all","my pleasure"],"distratoresEn":["Once again!","Please!","Whatever!","Not bad!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «of nothing»: «rien» means nothing. More formal: «Je vous en prie».","requerTodas":[],"v":"3c158524"},{"idioma":"fr","id":"fr-b008","tipo":"frase","fr":"S'il vous plaît.","aceitasFr":["S'il te plaît.","SVP"],"en":"Please.","aceitasEn":["please"],"distratoresEn":["Excuse me.","Thank you.","Sorry.","See you."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «if it pleases you». With people you call «tu» (friends, family, children) it becomes «s'il te plaît». In writing: «SVP».","requerTodas":[],"v":"dad0a242"},{"idioma":"fr","id":"fr-b009","tipo":"frase","fr":"Excusez-moi.","aceitasFr":["Excuse-moi.","Pardon."],"en":"Excuse me.","aceitasEn":["excuse me","pardon me","sorry"],"distratoresEn":["Please.","Thank you.","See you later.","Welcome."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"To get someone's attention, get past people, or apologize for something small. With «tu»: «Excuse-moi». «Pardon» does the same job.","requerTodas":[],"v":"446da295"},{"idioma":"fr","id":"fr-b010","tipo":"frase","fr":"Je suis désolé.","aceitasFr":["Je suis désolée.","Désolé.","Désolée."],"en":"I'm sorry.","aceitasEn":["i am sorry","sorry","im so sorry","i am so sorry"],"distratoresEn":["I'm tired.","I'm late.","Nice to meet you.","I don't know."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"A woman writes «désolée»; it sounds the same. It is the everyday apology, not a dramatic word.","requerTodas":[],"v":"7ca213a2"},{"idioma":"fr","id":"fr-b011","tipo":"frase","fr":"Oui, bien sûr.","aceitasFr":["Bien sûr.","Oui, bien sûr !","Oui, évidemment."],"en":"Yes, of course.","aceitasEn":["yes of course","of course","sure","yes sure","yes certainly","certainly"],"distratoresEn":["No, thank you.","Yes, maybe.","No, never.","Yes, later."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Bien sûr» means of course; literally «well sure». «Oui» sounds like «wee».","requerTodas":[],"v":"fc252c17"},{"idioma":"fr","id":"fr-b012","tipo":"frase","fr":"Non, merci.","aceitasFr":["Non merci."],"en":"No, thank you.","aceitasEn":["no thank you","no thanks"],"distratoresEn":["Yes, please.","No, never.","Yes, thank you.","Not now."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The polite refusal, to a waiter or anyone offering something. To accept: «Oui, merci» or «Oui, s'il vous plaît».","requerTodas":[],"v":"76959b07"},{"idioma":"fr","id":"fr-b013","tipo":"frase","fr":"Je ne comprends pas.","aceitasFr":["Je comprends pas."],"en":"I don't understand.","aceitasEn":["i do not understand","i dont understand","i dont get it"],"distratoresEn":["I don't agree.","I don't remember.","I can't.","I don't want to."],"nivel":"A1","tags":["primeiros passos","gramática"],"notaEn":"French negation has two parts: «ne» before the verb and «pas» after it. In speech the «ne» often drops («Je comprends pas»), but «pas» never does.","requerTodas":[],"v":"5ab567d0"},{"idioma":"fr","id":"fr-b014","tipo":"frase","fr":"Vous pouvez répéter, s'il vous plaît ?","aceitasFr":["Pouvez-vous répéter, s'il vous plaît ?","Tu peux répéter, s'il te plaît ?","Vous pouvez répéter ?"],"en":"Could you repeat that, please?","aceitasEn":["could you repeat that please","can you repeat that please","could you repeat please","can you say that again please","could you say that again please"],"distratoresEn":["Could you wait a moment, please?","Could you come in, please?","Could you write it down, please?","Could you sit down, please?"],"nivel":"A1","tags":["primeiros passos","escola"],"notaEn":"«Vous» is the polite you, for one person, and also the plural you. With friends: «Tu peux répéter ?».","requerTodas":[],"v":"edec3654"},{"idioma":"fr","id":"fr-b015","tipo":"frase","fr":"Vous parlez anglais ?","aceitasFr":["Parlez-vous anglais ?","Tu parles anglais ?","Est-ce que vous parlez anglais ?"],"en":"Do you speak English?","aceitasEn":["do you speak english","you speak english","can you speak english"],"distratoresEn":["Do you study English?","Do you understand English?","Do you teach English?","Do you like English?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"Languages are lowercase in French: «anglais», «français». Asking with just a rising tone, no inversion, is the everyday way.","requerTodas":[],"v":"777691a9"},{"idioma":"fr","id":"fr-b016","tipo":"frase","fr":"Je parle un peu français.","aceitasFr":["Je parle un petit peu français.","Je parle un peu le français."],"en":"I speak a little French.","aceitasEn":["i speak a little french","i speak a bit of french","i speak some french"],"distratoresEn":["I speak French very well.","I understand a little French.","I study a little French.","I speak a little English."],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«Un peu» is a little; «parler français» needs no article in this phrase.","requerTodas":[],"v":"b75ba417"},{"idioma":"fr","id":"fr-b017","tipo":"frase","fr":"Parlez plus lentement, s'il vous plaît.","aceitasFr":["Parle plus lentement, s'il te plaît.","Plus lentement, s'il vous plaît.","Vous pouvez parler plus lentement ?"],"en":"Please speak more slowly.","aceitasEn":["please speak more slowly","speak more slowly please","speak slower please","please speak slower","could you speak more slowly","slower please"],"distratoresEn":["Please speak louder.","Please speak more quietly.","Please walk more slowly.","Please write more slowly."],"nivel":"A1","tags":["primeiros passos","escola"],"notaEn":"«Parlez» is the «vous» imperative. «-ment» makes adverbs, like English «-ly»: «lentement», slowly.","requerTodas":[],"v":"6fc86399"},{"idioma":"fr","id":"fr-b018","tipo":"frase","fr":"Comment vous appelez-vous ?","aceitasFr":["Comment tu t'appelles ?","Tu t'appelles comment ?","Vous vous appelez comment ?","Quel est votre nom ?"],"en":"What's your name?","aceitasEn":["what is your name","whats your name","may i have your name"],"distratoresEn":["Where are you from?","Where do you live?","How old are you?","How are you doing?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «how do you call yourself?»: the verb is «s'appeler», to be called. Casually: «Tu t'appelles comment ?».","requerTodas":[],"v":"01c4665d"},{"idioma":"fr","id":"fr-b019","tipo":"frase","fr":"Je m'appelle Ana.","aceitasFr":["Moi, c'est Ana.","Mon nom est Ana.","Je suis Ana."],"en":"My name is Ana.","aceitasEn":["my name is ana","im ana","i am ana","my names ana"],"distratoresEn":["I live with Ana.","I'm calling Ana.","I'm Ana's friend.","Ana called me."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Je m'appelle» is literally «I call myself». Without the «m'», «J'appelle Ana» means I'm calling Ana. You also hear «Moi, c'est Ana».","requerTodas":[],"v":"51c43a18"},{"idioma":"fr","id":"fr-b020","tipo":"frase","fr":"Enchanté.","aceitasFr":["Enchantée.","Enchanté de vous connaître.","Ravi de vous rencontrer."],"en":"Nice to meet you.","aceitasEn":["nice to meet you","pleased to meet you","good to meet you","nice meeting you"],"distratoresEn":["Very tired.","Welcome.","See you soon.","Excuse me."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"A woman writes «enchantée»; it sounds the same. It is what you say when introduced; among young people «Salut» is enough.","requerTodas":[],"v":"99f1bf28"},{"idioma":"fr","id":"fr-b021","tipo":"frase","fr":"Ça va ?","aceitasFr":["Comment ça va ?","Ça va bien ?"],"en":"How's it going?","aceitasEn":["hows it going","how is it going","how are things"],"distratoresEn":["Is everything ready?","Are you leaving?","Who is it?","Where is it?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It is both the question and the answer: «— Ça va ? — Ça va.» Literally «it goes». Casual; with strangers, «Comment allez-vous ?».","requerTodas":[],"v":"2d61f16c"},{"idioma":"fr","id":"fr-b022","tipo":"frase","fr":"Ça va bien, merci.","aceitasFr":["Ça va, merci.","Très bien, merci.","Bien, merci.","Je vais bien, merci."],"en":"I'm fine, thanks.","aceitasEn":["im fine thanks","i am fine thanks","im fine thank you","i am fine thank you","fine thanks","fine thank you","im good thanks","good thanks","im well thanks"],"distratoresEn":["All set, thanks.","So-so, thanks.","I'm fine, and you?","I'm tired, thanks."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Ça va» is also the answer. Great: «Ça va très bien». So-so: «Comme ci, comme ça».","requerTodas":[],"v":"4c1fab22"},{"idioma":"fr","id":"fr-b023","tipo":"frase","fr":"Comment allez-vous ?","aceitasFr":["Vous allez bien ?","Comment vas-tu ?"],"en":"How are you?","aceitasEn":["how are you","how are you doing","how do you do"],"distratoresEn":["What is your name?","Where do you live?","Where are you going?","How did you get here?"],"nivel":"A1","tags":["primeiros passos","social","formal"],"notaEn":"The polite form, for people you call «vous». The verb is «aller», to go: «Où allez-vous ?» would be where are you going. Answer: «Je vais bien, merci».","requerTodas":[],"v":"6c0d7dfb"},{"idioma":"fr","id":"fr-b024","tipo":"frase","fr":"Et vous ?","aceitasFr":["Et toi ?","Et vous-même ?"],"en":"And you?","aceitasEn":["and you","what about you","how about you","and yourself"],"distratoresEn":["And then?","And so?","And now?","And why?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It bounces the question back: «— Ça va ? — Ça va, et toi ?». «Vous» is polite or plural; «toi» is for friends.","requerTodas":[],"v":"c60e1dbc"},{"idioma":"fr","id":"fr-b025","tipo":"frase","fr":"Où sont les toilettes ?","aceitasFr":["Où sont les toilettes, s'il vous plaît ?","Les toilettes, s'il vous plaît ?","Où se trouvent les toilettes ?"],"en":"Where is the restroom?","aceitasEn":["where is the restroom","wheres the restroom","where is the bathroom","wheres the bathroom","where are the restrooms","where is the toilet"],"distratoresEn":["Where is the exit?","Where is the kitchen?","Where is the bedroom?","Where is the elevator?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"The French word is always plural, «les toilettes», even for a single restroom. «Où» with the accent means where; «ou» without it means or.","requerTodas":[],"v":"73f27ec0"},{"idioma":"fr","id":"fr-b026","tipo":"frase","fr":"C'est combien ?","aceitasFr":["Ça coûte combien ?","Combien ça coûte ?","Combien ?"],"en":"How much is it?","aceitasEn":["how much is it","how much","how much does it cost","how much is this","how much does this cost"],"distratoresEn":["How much is left?","How long does it take?","When does it open?","Where is it?"],"nivel":"A1","tags":["primeiros passos","compras"],"notaEn":"Literally «it's how much?», with «combien» at the end, which is how people ask in conversation.","requerTodas":[],"v":"d5589339"},{"idioma":"fr","id":"fr-b027","tipo":"frase","fr":"L'addition, s'il vous plaît.","aceitasFr":["L'addition, s'il te plaît.","L'addition !"],"en":"The check, please.","aceitasEn":["the check please","check please","can i have the check please","could we have the check please"],"regionaisEn":{"The bill, please.":"no Reino Unido"},"distratoresEn":["The menu, please.","Some water, please.","My change, please.","A table, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"At a restaurant the check is «l'addition», literally the sum. A bank account is «le compte».","requerTodas":[],"v":"a9d76f97"},{"idioma":"fr","id":"fr-b028","tipo":"frase","fr":"Je voudrais un café, s'il vous plaît.","aceitasFr":["Un café, s'il vous plaît.","Je voudrais un café.","Je prendrais un café, s'il vous plaît."],"en":"I'd like a coffee, please.","aceitasEn":["id like a coffee please","i would like a coffee please","a coffee please","can i have a coffee please","could i have a coffee please","coffee please"],"distratoresEn":["I'd like a tea, please.","I had a coffee, thanks.","I'll pay for the coffee.","I'd like some water, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"«Je voudrais» is the conditional of «vouloir», to want: the polite request, like I'd like. «Je veux» sounds blunt. In France «un café» is an espresso.","requerTodas":[],"v":"a63f101d"},{"idioma":"fr","id":"fr-b029","tipo":"frase","fr":"Une table pour deux, s'il vous plaît.","aceitasFr":["Une table pour deux personnes, s'il vous plaît.","Une table pour deux."],"en":"A table for two, please.","aceitasEn":["a table for two please","table for two please","a table for two","a table for two people please"],"distratoresEn":["A table for three, please.","A chair for two, please.","A room for two, please.","A table by the window, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"«La table» is feminine. The «x» in «deux» is silent.","requerTodas":[],"v":"9ab6a148"},{"idioma":"fr","id":"fr-b030","tipo":"frase","fr":"Où est la gare ?","aceitasFr":["Où se trouve la gare ?","La gare, c'est où ?","Où est la gare, s'il vous plaît ?"],"en":"Where is the train station?","aceitasEn":["where is the train station","wheres the train station","where is the station","wheres the station","where is the railway station"],"distratoresEn":["Where is the hotel?","Where is the beach?","Where is the bus stop?","Where is the garage?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«La gare» is the train station; a subway station is «la station». A garage is «le garage».","requerTodas":[],"v":"5becc440"},{"idioma":"fr","id":"fr-b031","tipo":"frase","fr":"Je suis perdu.","aceitasFr":["Je suis perdue."],"en":"I'm lost.","aceitasEn":["im lost","i am lost"],"distratoresEn":["I'm tired.","I'm late.","I'm ready.","I'm hungry."],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"A woman writes «perdue»; it sounds the same.","requerTodas":[],"v":"c7484a34"},{"idioma":"fr","id":"fr-b032","tipo":"frase","fr":"J'ai faim.","aceitasFr":["J'ai très faim."],"en":"I'm hungry.","aceitasEn":["im hungry","i am hungry"],"distratoresEn":["I'm thirsty.","I'm cold.","I'm sleepy.","I'm in a hurry."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"French «has» hunger: «avoir faim», literally to have hunger. Likewise «avoir soif» (thirsty), «avoir froid» (cold), «avoir sommeil» (sleepy).","requerTodas":[],"v":"7207b812"},{"idioma":"fr","id":"fr-b033","tipo":"frase","fr":"Je ne sais pas.","aceitasFr":["Je sais pas."],"en":"I don't know.","aceitasEn":["i dont know","i do not know","no idea","dunno"],"distratoresEn":["I can't.","I don't want to.","I don't remember.","I don't like it."],"nivel":"A1","tags":["primeiros passos","gramática"],"notaEn":"«Savoir» is to know: «je sais», I know. In speech the «ne» drops: «Je sais pas».","requerTodas":[],"v":"52c3a0e2"},{"idioma":"fr","id":"fr-b034","tipo":"frase","fr":"Aidez-moi, s'il vous plaît !","aceitasFr":["Aide-moi, s'il te plaît !","Vous pouvez m'aider, s'il vous plaît ?","Aidez-moi !"],"en":"Please help me!","aceitasEn":["please help me","help me please","can you help me please","could you help me please","help me"],"distratoresEn":["Please wait for me!","Please call me!","Please forgive me!","Please listen to me!"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«Aider» is to help. With «tu»: «Aide-moi». In an emergency, shout «Au secours !».","requerTodas":[],"v":"ad337e09"},{"idioma":"fr","id":"fr-b035","tipo":"frase","fr":"Vous venez d'où ?","aceitasFr":["Tu viens d'où ?","D'où venez-vous ?","Vous êtes d'où ?"],"en":"Where are you from?","aceitasEn":["where are you from","where do you come from","where you from"],"distratoresEn":["Where do you live?","Where are you going?","Where have you been?","Where do you work?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «you come from where?»: «venir» is to come. In conversation the question word goes at the end.","requerTodas":[],"v":"a1f04bb2"},{"idioma":"fr","id":"fr-b036","tipo":"frase","fr":"Je viens du Brésil.","aceitasFr":["Je suis du Brésil.","Je suis brésilien.","Je suis brésilienne."],"en":"I'm from Brazil.","aceitasEn":["im from brazil","i am from brazil","i come from brazil","im brazilian","i am brazilian"],"distratoresEn":["I live in Brazil.","I'm going to Brazil.","I'm back from Brazil.","I like Brazil."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Masculine countries take «du»: «du Brésil», «du Canada»; feminine ones take «de»: «de France», «d'Angleterre». «Je viens» means I come.","requerTodas":[],"v":"1edad4f2"},{"idioma":"fr","id":"fr-b037","tipo":"frase","fr":"Quelle heure est-il ?","aceitasFr":["Il est quelle heure ?","Vous avez l'heure ?","Tu as l'heure ?"],"en":"What time is it?","aceitasEn":["what time is it","whats the time","what is the time","do you have the time"],"distratoresEn":["How old are you?","What day is it today?","What time does it open?","How much time is left?"],"nivel":"A1","tags":["primeiros passos","cotidiano"],"notaEn":"Literally «what hour is it?». The answer uses the same frame: «Il est trois heures», it's three o'clock.","requerTodas":[],"v":"b23dfd08"},{"idioma":"fr","id":"fr-b038","tipo":"frase","fr":"À bientôt !","aceitasFr":["À plus tard !","À la prochaine !","À plus !"],"en":"See you soon!","aceitasEn":["see you soon","see you","see you later","talk soon"],"distratoresEn":["See you tomorrow!","Welcome!","Have a good trip!","Enjoy your meal!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Bientôt» means soon. For tomorrow: «À demain !». Among friends, the short «À plus !» (the «s» is pronounced).","requerTodas":[],"v":"8ea86a8a"},{"idioma":"fr","id":"fr-b039","tipo":"frase","fr":"Bon appétit !","aceitasFr":["Bon appétit."],"en":"Enjoy your meal!","aceitasEn":["enjoy your meal","enjoy","bon appetit"],"distratoresEn":["Have a nice trip!","Good luck!","Cheers!","Sleep well!"],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"Said before eating; English borrowed it as is. The final «t» is silent.","requerTodas":[],"v":"15dea5d1"},{"idioma":"fr","id":"fr-b040","tipo":"frase","fr":"Bonne journée !","aceitasFr":["Bonne journée.","Passez une bonne journée !","Bonne journée à vous !"],"en":"Have a nice day!","aceitasEn":["have a nice day","have a good day","have a great day","enjoy your day"],"distratoresEn":["Have a nice evening!","Have a nice trip!","Have a nice weekend!","Have a nice lunch!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It's a goodbye, not a greeting: «Bonjour» when you arrive, «Bonne journée» when you leave. In the evening, «Bonne soirée».","requerTodas":[],"v":"da6a32ad"},{"idioma":"fr","id":"fr-p001","tipo":"palavra","fr":"être","en":"to be","aceitasEn":["to be","be"],"distratoresEn":["to have","to do","to stay","to give"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"Irregular: je suis, tu es, il est, nous sommes, vous êtes, ils sont. It is also the helper verb of some past tenses: «je suis allé», I went.","v":"e2b9cdca"},{"idioma":"fr","id":"fr-p002","tipo":"palavra","fr":"avoir","en":"to have","aceitasEn":["to have","have","to have got"],"distratoresEn":["to hear","to owe","to be worth","to know"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"French uses it for age and sensations: «j'ai vingt ans» (I'm twenty), «j'ai faim» (I'm hungry). Forms: j'ai, tu as, il a, nous avons, vous avez, ils ont.","v":"a7406585"},{"idioma":"fr","id":"fr-p003","tipo":"palavra","fr":"aller","en":"to go","aceitasEn":["to go","go"],"distratoresEn":["to rent","to stay","to take","to look"],"nivel":"A1","tags":["verbo"],"notaEn":"Very irregular: je vais, tu vas, il va, nous allons, vous allez, ils vont. It is in «Ça va ?» and in the near future: «je vais manger», I'm going to eat.","v":"6fc8aa32"},{"idioma":"fr","id":"fr-p004","tipo":"palavra","fr":"faire","en":"to do / to make","aceitasEn":["to do","to make","do","make"],"distratoresEn":["to speak / to say","to hurt / to injure","to boil / to heat","to close / to shut"],"nivel":"A1","tags":["verbo"],"notaEn":"Both to do and to make, and also the weather verb: «il fait beau» (it's nice out), «il fait froid» (it's cold). Forms: je fais, nous faisons, vous faites, ils font.","v":"f0f41628"},{"idioma":"fr","id":"fr-p005","tipo":"palavra","fr":"dire","en":"to say","aceitasEn":["to say","say","to tell","tell"],"distratoresEn":["to drive","to last","to leave","to owe"],"nivel":"A1","tags":["verbo"],"notaEn":"To say or tell something; to speak a language, or to talk, is «parler». Forms: je dis, nous disons, vous dites, ils disent.","v":"fe7eef1f"},{"idioma":"fr","id":"fr-p006","tipo":"palavra","fr":"pouvoir","en":"can / to be able to","aceitasEn":["can","to be able to","be able to","to be able"],"distratoresEn":["must / to have to","to be worth / to cost","to put / to place","to know / to know how"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je peux, tu peux, il peut, nous pouvons, vous pouvez, ils peuvent. To ask permission: «Je peux… ?», or formally «Puis-je… ?».","v":"1c72f625"},{"idioma":"fr","id":"fr-p007","tipo":"palavra","fr":"vouloir","en":"to want","aceitasEn":["to want","want","to wish"],"distratoresEn":["to fly","to be worth","to return","to live"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je veux, tu veux, il veut, nous voulons, ils veulent. Polite requests use the conditional: «je voudrais», I'd like. «Vouloir dire» means to mean.","v":"b3c5e3ae"},{"idioma":"fr","id":"fr-p008","tipo":"palavra","fr":"savoir","en":"to know","aceitasEn":["to know","know","to know how to"],"distratoresEn":["to meet","to save","to serve","to follow"],"nivel":"A1","tags":["verbo"],"notaEn":"To know a fact, or how to do something: «je sais nager», I can swim. Knowing a person or a place is another verb, «connaître». Forms: je sais, nous savons, ils savent.","v":"92ac684b"},{"idioma":"fr","id":"fr-p009","tipo":"palavra","fr":"venir","en":"to come","aceitasEn":["to come","come"],"distratoresEn":["to sell","to win","to see","to dress"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je viens, nous venons, ils viennent. «Venir de» + infinitive means to have just: «je viens de manger», I've just eaten.","v":"2f117e21"},{"idioma":"fr","id":"fr-p010","tipo":"palavra","fr":"voir","en":"to see","aceitasEn":["to see","see"],"distratoresEn":["to fly","to come","to be worth","to dress"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je vois, nous voyons, ils voient. To look at or watch is «regarder». «On verra», we'll see.","v":"b7d5b90d"},{"idioma":"fr","id":"fr-p011","tipo":"palavra","fr":"prendre","en":"to take","aceitasEn":["to take","take","to grab"],"distratoresEn":["to learn","to lose","to ask for","to lend"],"nivel":"A1","tags":["verbo","falso-amigo"],"notaEn":"To take: «prendre le bus», to take the bus; «prendre un café», to have a coffee. With «ap-», «apprendre» means to learn. Forms: je prends, nous prenons, ils prennent.","v":"786aaff8"},{"idioma":"fr","id":"fr-p012","tipo":"palavra","fr":"parler","en":"to speak","aceitasEn":["to speak","speak","to talk","talk"],"distratoresEn":["to stop","to leave","to pay","to jump"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, the pattern most verbs follow: je parle, tu parles, il parle (all three sound the same), nous parlons, vous parlez, ils parlent.","v":"31194517"},{"idioma":"fr","id":"fr-p013","tipo":"palavra","fr":"manger","en":"to eat","aceitasEn":["to eat","eat"],"distratoresEn":["to send","to move","to change","to bite"],"nivel":"A1","tags":["verbo","comida"],"notaEn":"Regular «-er» verb, with an extra «e» in «nous mangeons» to keep the soft «g». A meal is «un repas».","v":"924863aa"},{"idioma":"fr","id":"fr-p014","tipo":"palavra","fr":"boire","en":"to drink","aceitasEn":["to drink","drink"],"distratoresEn":["to beat","to kiss","to play","to look for"],"nivel":"A1","tags":["verbo","comida"],"notaEn":"Irregular: je bois, nous buvons, ils boivent; past participle «bu». A drink is «une boisson».","v":"af44509e"},{"idioma":"fr","id":"fr-p015","tipo":"palavra","fr":"aimer","en":"to love / to like","aceitasEn":["to love","to like"],"distratoresEn":["to help / to support","to accept / to admit","to find / to discover","to hate / to detest"],"nivel":"A1","tags":["verbo","família"],"notaEn":"Both to love and to like: «je t'aime» (I love you), «j'aime le café» (I like coffee). Things you like take the article: «j'aime le café», not «j'aime café».","v":"d136d30f"},{"idioma":"fr","id":"fr-p016","tipo":"palavra","fr":"habiter","en":"to live (somewhere)","aceitasEn":["to live","live","to reside","reside","to live in"],"distratoresEn":["to hesitate (to doubt)","to inherit (property)","to host (a guest)","to shelter (from cold)"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"To live somewhere: «j'habite à Paris», I live in Paris. The «h» is silent, hence the apostrophe: «j'habite». «Vivre» is to live in the broader sense.","v":"ff2f69e2"},{"idioma":"fr","id":"fr-p017","tipo":"palavra","fr":"travailler","en":"to work","aceitasEn":["to work","work"],"distratoresEn":["to block","to treat","to travel","to swap"],"nivel":"A1","tags":["verbo","trabalho"],"notaEn":"Regular «-er» verb: je travaille, nous travaillons. The «-ill-» sounds like «y»: «tra-va-YAY». Work, the noun, is «le travail».","v":"ab9766f3"},{"idioma":"fr","id":"fr-p018","tipo":"palavra","fr":"attendre","en":"to wait","aceitasEn":["to wait","wait","to wait for","wait for"],"distratoresEn":["to attend","to understand","to extend","to tend"],"nivel":"A1","tags":["verbo","falso-amigo"],"notaEn":"Not to attend: it means to wait for, with no preposition: «j'attends le bus», I'm waiting for the bus. To attend is «assister à».","v":"8639d0d0"},{"idioma":"fr","id":"fr-p019","tipo":"palavra","fr":"le jour","en":"the day","aceitasEn":["the day","day"],"distratoresEn":["the game","the newspaper","the month","the year"],"nivel":"A1","tags":["cotidiano"],"notaEn":"A day on the calendar. The day as you live it, the daytime, is «la journée»: «bonne journée». «Bonjour» is literally good day.","v":"e87a7825"},{"idioma":"fr","id":"fr-p020","tipo":"palavra","fr":"la maison","en":"the house","aceitasEn":["the house","house","the home","home"],"distratoresEn":["the table","the mansion","the dough","the apple"],"nivel":"A1","tags":["casa"],"notaEn":"«À la maison» means at home: «je suis à la maison». «Chez moi» also means at my place.","v":"bde2f8bf"},{"idioma":"fr","id":"fr-p021","tipo":"palavra","fr":"l'homme","aceitasFr":["un homme"],"en":"the man","aceitasEn":["the man","man"],"distratoresEn":["the name","the shoulder","the guest","the anthem"],"nivel":"A1","tags":["família"],"notaEn":"Masculine, with the article shortened before the silent «h»: «l'homme», «un homme».","v":"510c8580"},{"idioma":"fr","id":"fr-p022","tipo":"palavra","fr":"la femme","en":"the woman","aceitasEn":["the woman","woman","the wife","wife"],"distratoresEn":["the hunger","the daughter","the company","the shape"],"nivel":"A1","tags":["família"],"notaEn":"Also wife: «ma femme», my wife. Pronounced «fam», with an «a».","v":"ff3b66a3"},{"idioma":"fr","id":"fr-p023","tipo":"palavra","fr":"l'enfant","aceitasFr":["un enfant","une enfant"],"en":"the child","aceitasEn":["the child","child","the kid","kid"],"distratoresEn":["the childhood","the patient","the godson","the nephew"],"nivel":"A1","tags":["família"],"notaEn":"For a boy or a girl: «un enfant», «une enfant». «Les enfants» also means your children: «j'ai deux enfants». Childhood is «l'enfance».","v":"ed14078b"},{"idioma":"fr","id":"fr-p024","tipo":"palavra","fr":"l'ami","aceitasFr":["l'amie","un ami","une amie"],"en":"the friend","aceitasEn":["the friend","friend"],"distratoresEn":["the love","the lunch","the student","the neighbor"],"nivel":"A1","tags":["família","social"],"notaEn":"A female friend is «l'amie»; it sounds the same. Boyfriend and girlfriend are «le petit ami» and «la petite amie».","v":"43fe5878"},{"idioma":"fr","id":"fr-p025","tipo":"palavra","fr":"le temps","en":"time / weather","aceitasEn":["time","the time","weather","the weather"],"distratoresEn":["temple / church","seasoning / spice","ceiling / roof","topic / theme"],"nivel":"A1","tags":["cotidiano","natureza"],"notaEn":"Both time and weather: «je n'ai pas le temps» (I don't have time), «quel temps fait-il ?» (what's the weather like?). The «p» and «s» are silent.","v":"e46e6345"},{"idioma":"fr","id":"fr-p026","tipo":"palavra","fr":"l'eau","aceitasFr":["une eau"],"en":"the water","aceitasEn":["the water","water"],"distratoresEn":["the wave","the bird","the island","the grape"],"nivel":"A1","tags":["comida","natureza"],"notaEn":"Feminine: «une eau», «l'eau minérale». Three letters for one vowel sound: «oh».","v":"af06924e"},{"idioma":"fr","id":"fr-p027","tipo":"palavra","fr":"le pain","en":"the bread","aceitasEn":["the bread","bread"],"distratoresEn":["the cloth","the father","the foot","the pine"],"nivel":"A1","tags":["comida"],"notaEn":"«Ain» is a nasal vowel, with no «n» sound at the end. A baguette is «une baguette»; the baker is «le boulanger», in the «boulangerie».","v":"d1e9e55a"},{"idioma":"fr","id":"fr-p028","tipo":"palavra","fr":"la ville","en":"the city","aceitasEn":["the city","city","the town","town"],"distratoresEn":["the village","the life","the candle","the track"],"nivel":"A1","tags":["cidade","falso-amigo"],"notaEn":"A city or town of any size. A village is «le village»; a big country house is «une villa». «En ville», downtown.","v":"a2347337"},{"idioma":"fr","id":"fr-p029","tipo":"palavra","fr":"le travail","en":"work","aceitasEn":["work","the work","job","the job"],"distratoresEn":["clover","pillow","journey","theater"],"nivel":"A1","tags":["trabalho"],"notaEn":"Work and job: «je vais au travail», I'm going to work. Irregular plural: «les travaux», roadworks or renovations.","v":"c12a261e"},{"idioma":"fr","id":"fr-p030","tipo":"palavra","fr":"la nuit","en":"the night","aceitasEn":["the night","night"],"distratoresEn":["the cloud","the snow","the note","the nape"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Bonne nuit» is what you say at bedtime; arriving in the evening, it's «Bonsoir». The evening, after work, is «le soir».","v":"46f21d60"},{"idioma":"fr","id":"fr-p031","tipo":"palavra","fr":"l'année","aceitasFr":["une année"],"en":"the year","aceitasEn":["the year","year"],"distratoresEn":["the ring","the owner","the nest","the month"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. French has two words for year: «l'an» for counting («j'ai vingt ans», I'm twenty) and «l'année» for the year as lived («bonne année !», happy new year).","v":"a8bbbecc"},{"idioma":"fr","id":"fr-p032","tipo":"palavra","fr":"la rue","en":"the street","aceitasEn":["the street","street"],"distratoresEn":["the wheel","the clothes","the wrinkle","the ruler"],"nivel":"A1","tags":["cidade"],"notaEn":"A city street; a road out of town is «la route». «Dans la rue», in the street.","v":"0e832e13"},{"idioma":"fr","id":"fr-p033","tipo":"palavra","fr":"le livre","en":"the book","aceitasEn":["the book","book"],"distratoresEn":["the lily","the liter","the lip","the canvas"],"nivel":"A1","tags":["escola"],"notaEn":"Masculine. Feminine «la livre» is the pound (money or weight). Free is «libre».","v":"135ab3cb"},{"idioma":"fr","id":"fr-p034","tipo":"palavra","fr":"la voiture","en":"the car","aceitasEn":["the car","car","the automobile"],"distratoresEn":["the bus","the truck","the train","the flight"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Feminine in French: «une voiture», «ma voiture». To drive is «conduire».","v":"74004096"},{"idioma":"fr","id":"fr-p035","tipo":"palavra","fr":"l'argent","en":"money","aceitasEn":["money","the money","silver"],"distratoresEn":["gold","argument","change","card"],"nivel":"A1","tags":["compras","economia"],"notaEn":"Masculine. It means money and also silver, the metal.","v":"a03959da"},{"idioma":"fr","id":"fr-p036","tipo":"palavra","fr":"bon","aceitasFr":["bonne"],"en":"good","aceitasEn":["good","tasty"],"distratoresEn":["pretty","cheap","brief","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «bonne». For food it means tasty: «c'est bon !». The adverb, well, is «bien».","v":"e4bdf42a"},{"idioma":"fr","id":"fr-p037","tipo":"palavra","fr":"grand","aceitasFr":["grande"],"en":"big","aceitasEn":["big","large","great","tall"],"distratoresEn":["thick","fat","free","serious"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «grande». For people it also means tall: «il est grand», he is tall. The «d» is only heard in the feminine.","v":"768a98eb"},{"idioma":"fr","id":"fr-p038","tipo":"palavra","fr":"petit","aceitasFr":["petite"],"en":"small","aceitasEn":["small","little","short"],"distratoresEn":["few","heavy","slow","poor"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «petite». Before nouns it can sound affectionate: «un petit café». Breakfast is «le petit déjeuner».","v":"4149551f"},{"idioma":"fr","id":"fr-p039","tipo":"palavra","fr":"nouveau","aceitasFr":["nouvelle","nouvel"],"en":"new","aceitasEn":["new"],"distratoresEn":["nine","engaged","cloudy","noble"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Three forms: «nouveau»; «nouvel» before a vowel («un nouvel ami»); feminine «nouvelle». Brand-new, unused, is «neuf».","v":"9350aae7"},{"idioma":"fr","id":"fr-p040","tipo":"palavra","fr":"beau","aceitasFr":["belle","bel"],"en":"beautiful","aceitasEn":["beautiful","pretty","handsome","lovely"],"distratoresEn":["good","short","cheap","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «belle»; before a vowel, «bel» («un bel homme»). Also nice weather: «il fait beau», it's a lovely day.","v":"15edc663"},{"idioma":"fr","id":"fr-p041","tipo":"palavra","fr":"vieux","aceitasFr":["vieille","vieil"],"en":"old","aceitasEn":["old","elderly","aged"],"distratoresEn":["empty","widowed","alive","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «vieille»; before a vowel, «vieil» («un vieil ami», an old friend). For people, «âgé» (elderly) is more polite.","v":"eaf559c6"},{"idioma":"fr","id":"fr-p042","tipo":"palavra","fr":"content","aceitasFr":["contente"],"en":"happy","aceitasEn":["happy","glad","pleased","content"],"distratoresEn":["tired","known","restrained","hot"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «contente». With «de»: «je suis content de te voir», I'm glad to see you.","v":"09fc7831"},{"idioma":"fr","id":"fr-p043","tipo":"palavra","fr":"très","en":"very","aceitasEn":["very","really"],"distratoresEn":["three","behind","late","so much"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Goes before adjectives and adverbs: «très bien», «très grand». The number three is «trois».","v":"216e5f2f"},{"idioma":"fr","id":"fr-p044","tipo":"palavra","fr":"bien","en":"well","aceitasEn":["well","fine"],"distratoresEn":["soon","badly","far","early"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The adverb: «je vais bien», I'm well. The adjective is «bon»: «un bon livre». With «c'est» it praises: «c'est bien», that's good.","v":"fd01d39d"},{"idioma":"fr","id":"fr-p045","tipo":"palavra","fr":"aussi","en":"also","aceitasEn":["also","too","as well"],"distratoresEn":["like this","still","then","only"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Also, too: «moi aussi», me too. In comparisons it means as: «aussi grand que moi», as tall as me.","v":"194f7966"},{"idioma":"fr","id":"fr-p046","tipo":"palavra","fr":"toujours","en":"always / still","aceitasEn":["always","still"],"distratoresEn":["never / ever","sometimes / rarely","today / now","afterwards / finally"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Always, and also still: «il habite toujours ici», he still lives here. It comes from «tous les jours», every day.","v":"bb5b9bed"},{"idioma":"fr","id":"fr-p047","tipo":"palavra","fr":"maintenant","en":"now","aceitasEn":["now","right now"],"distratoresEn":["tomorrow","before","afterwards","yesterday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Now. Right away is «tout de suite».","v":"107fbbd9"},{"idioma":"fr","id":"fr-p048","tipo":"palavra","fr":"ici","en":"here","aceitasEn":["here"],"distratoresEn":["there","like this","over there","nearby"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Here. In conversation French also uses «là» this way: «je suis là», I'm here.","v":"9e8a712d"},{"idioma":"fr","id":"fr-p049","tipo":"palavra","fr":"aujourd'hui","en":"today","aceitasEn":["today"],"distratoresEn":["yesterday","tomorrow","now","later"],"nivel":"A1","tags":["cotidiano"],"notaEn":"One word, with an apostrophe. Yesterday is «hier»; tomorrow, «demain».","v":"a48d791b"},{"idioma":"fr","id":"fr-p050","tipo":"palavra","fr":"déjà","en":"already","aceitasEn":["already","yet","ever"],"distratoresEn":["still","afterwards","soon","before"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Already: «j'ai déjà mangé», I've already eaten. In questions it means ever: «tu es déjà allé à Paris ?», have you ever been to Paris?","v":"3c6a193b"},{"idioma":"fr","id":"fr-u001","tipo":"frase","requer":"fr-p001","fr":"Elle est très contente.","en":"She's very happy.","aceitasEn":["shes very happy","she is very happy","shes really happy","she is really happy","shes very glad","she is very pleased"],"distratoresEn":["She seems very happy.","She gets very happy.","She's still very happy.","She used to be very happy."],"nivel":"A1","tags":["gramática","social"],"notaEn":"«Est» is the «il»/«elle» form of «être»; the «st» is silent, so it sounds like «et» (and). The adjective agrees: «contente», with an «e», because she is the subject.","requerTodas":["fr-p001","fr-p043","fr-p042"],"v":"5c05a823"},{"idioma":"fr","id":"fr-u002","tipo":"frase","requer":"fr-p001","fr":"Je suis à la maison.","aceitasFr":["Je suis chez moi."],"en":"I'm at home.","aceitasEn":["im at home","i am at home","im home","i am home"],"distratoresEn":["I'm staying home.","I work at home.","I eat at home.","I sleep at home."],"nivel":"A1","tags":["gramática","casa"],"notaEn":"«Être» also covers location. «À la maison», at home; «chez moi», at my place.","requerTodas":["fr-p001","fr-p020"],"v":"2f4c02b0"},{"idioma":"fr","id":"fr-u003","tipo":"frase","requer":"fr-p001","fr":"C'est un bon livre.","en":"It's a good book.","aceitasEn":["its a good book","it is a good book","this is a good book","thats a good book"],"distratoresEn":["It was a good book.","It seems like a good book.","It's been a good book.","It will be a good book."],"nivel":"A1","tags":["gramática","escola"],"notaEn":"«C'est» (it is, this is) introduces things: «c'est un bon livre», «c'est mon ami». «Bon» goes before the noun.","requerTodas":["fr-p001","fr-p036","fr-p033"],"v":"fa795f29"},{"idioma":"fr","id":"fr-u004","tipo":"frase","requer":"fr-p002","fr":"J'ai vingt ans.","en":"I'm twenty years old.","aceitasEn":["im twenty years old","i am twenty years old","im twenty","i am twenty","im 20","im 20 years old"],"distratoresEn":["I'm turning twenty.","I'm twenty months old.","Twenty years ago.","I'm twenty days old."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"In French you have an age instead of being it: «j'ai vingt ans», literally I have twenty years. For counting years the word is «an», not «année».","requerTodas":["fr-p002","+vingt","+l'an"],"v":"c8ad3ea1"},{"idioma":"fr","id":"fr-u005","tipo":"frase","requer":"fr-p002","fr":"Il y a un problème.","en":"There's a problem.","aceitasEn":["theres a problem","there is a problem"],"distratoresEn":["It's a problem.","I see a problem.","It was a problem.","I have a problem."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Il y a» is there is / there are. The verb is «avoir», and «il» refers to nobody. «C'est un problème» would be it's a problem.","requerTodas":["fr-p002","+le problème"],"v":"9c22257e"},{"idioma":"fr","id":"fr-u006","tipo":"frase","requer":"fr-p003","fr":"Je vais au travail.","en":"I'm going to work.","aceitasEn":["im going to work","i am going to work","i go to work","im off to work"],"distratoresEn":["I'm coming back from work.","I'm leaving work.","I'm getting to work.","I'm staying at work."],"nivel":"A1","tags":["gramática","trabalho"],"notaEn":"«Au» is «à» + «le» fused. Before a feminine noun there's no fusion: «à la maison».","requerTodas":["fr-p003","fr-p029"],"v":"7fccba40"},{"idioma":"fr","id":"fr-u007","tipo":"frase","requer":"fr-p004","fr":"Il fait beau aujourd'hui.","aceitasFr":["Aujourd'hui, il fait beau."],"en":"The weather is nice today.","aceitasEn":["the weather is nice today","its nice out today","its a nice day today","the weather is good today","its beautiful today","the weather is lovely today"],"distratoresEn":["The weather is bad today.","It's cold today.","It's hot today.","It's cloudy today."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"French «makes» the weather: «il fait beau» (it's nice), «il fait froid» (it's cold), «il fait chaud» (it's hot). The «il» is a dummy subject, like English it.","requerTodas":["fr-p004","fr-p040","fr-p049"],"v":"d7c9038a"},{"idioma":"fr","id":"fr-u008","tipo":"frase","requer":"fr-p004","fr":"Qu'est-ce que tu fais ?","aceitasFr":["Tu fais quoi ?","Que fais-tu ?"],"en":"What are you doing?","aceitasEn":["what are you doing","what do you do","what are you up to"],"distratoresEn":["What are you saying?","What are you looking at?","What are you eating?","What do you want?"],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Qu'est-ce que» (what is it that) is the everyday way to ask what. The French present covers both what do you do and what are you doing.","requerTodas":["fr-p004"],"v":"c246341b"},{"idioma":"fr","id":"fr-u009","tipo":"frase","requer":"fr-p005","fr":"Comment on dit ça en français ?","aceitasFr":["Comment dit-on ça en français ?","Comment est-ce qu'on dit ça en français ?"],"en":"How do you say this in French?","aceitasEn":["how do you say this in french","how do you say that in french","how do we say this in french","how is this said in french","whats this in french","what is this in french"],"distratoresEn":["How do you spell this in French?","How do you read this in French?","How do you use this in French?","How do you pronounce this in French?"],"nivel":"A1","tags":["escola"],"notaEn":"«On» is the impersonal one or people, and the casual we: «on dit», people say. It takes the «il» form of the verb.","requerTodas":["fr-p005","+le français"],"v":"3c4ed36c"},{"idioma":"fr","id":"fr-u010","tipo":"frase","requer":"fr-p005","fr":"Elle dit toujours la vérité.","en":"She always tells the truth.","aceitasEn":["she always tells the truth"],"distratoresEn":["She always asks for the truth.","She always knows the truth.","She always wants the truth.","She always hides the truth."],"nivel":"A1","tags":["social"],"notaEn":"«Toujours» comes after the verb: «elle dit toujours», never «elle toujours dit».","requerTodas":["fr-p005","fr-p046","+la vérité"],"v":"42ba8e79"},{"idioma":"fr","id":"fr-u011","tipo":"frase","requer":"fr-p006","fr":"Je peux entrer ?","aceitasFr":["Puis-je entrer ?","Est-ce que je peux entrer ?"],"en":"Can I come in?","aceitasEn":["can i come in","may i come in","could i come in","can i go in"],"distratoresEn":["Should I come in?","Can I go out?","Can I sit down?","Can I wait?"],"nivel":"A1","tags":["social"],"notaEn":"A rising tone is enough to ask permission: «Je peux… ?». More formal: «Puis-je entrer ?».","requerTodas":["fr-p006","+entrer"],"v":"d5e0353d"},{"idioma":"fr","id":"fr-u012","tipo":"frase","requer":"fr-p006","fr":"On ne peut pas parler ici.","en":"You can't talk here.","aceitasEn":["you cant talk here","you cannot talk here","we cant talk here","you cant speak here","no talking here"],"distratoresEn":["You shouldn't talk here.","People don't usually talk here.","You can't smoke here.","You can't eat here."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«On» is the impersonal subject: «on ne peut pas», one can't. The negation wraps the conjugated verb, leaving the infinitive outside: «ne peut pas parler».","requerTodas":["fr-p006","fr-p012","fr-p048"],"v":"3d7cdb5b"},{"idioma":"fr","id":"fr-u013","tipo":"frase","requer":"fr-p007","fr":"Tu veux un café ?","aceitasFr":["Vous voulez un café ?","Tu veux du café ?"],"en":"Do you want a coffee?","aceitasEn":["do you want a coffee","do you want some coffee","want a coffee","would you like a coffee","you want a coffee"],"distratoresEn":["Do you have a coffee?","Are you having a coffee?","Are you making a coffee?","Are you paying for a coffee?"],"nivel":"A1","tags":["comida","social"],"notaEn":"«Tu» for people you're close to; «vous» for everyone else: «Vous voulez un café ?». Even more polite: «Tu voudrais un café ?».","requerTodas":["fr-p007","+le café"],"v":"b3adc581"},{"idioma":"fr","id":"fr-u014","tipo":"frase","requer":"fr-p007","fr":"Qu'est-ce que ça veut dire ?","aceitasFr":["Ça veut dire quoi ?","Qu'est-ce que cela veut dire ?"],"en":"What does that mean?","aceitasEn":["what does that mean","what does this mean","whats that mean","what does it mean"],"distratoresEn":["What does that have to do with it?","What do you mean?","What does he want to do?","Where is that going?"],"nivel":"A1","tags":["escola"],"notaEn":"«Vouloir dire», literally to want to say, is the everyday to mean. «Ça» is that. Compare «Qu'est-ce que tu veux dire ?», what do you mean?","requerTodas":["fr-p007","fr-p005"],"v":"d63c0c98"},{"idioma":"fr","id":"fr-u015","tipo":"frase","requer":"fr-p008","fr":"Je sais nager.","en":"I can swim.","aceitasEn":["i can swim","i know how to swim"],"distratoresEn":["I'm allowed to swim.","I want to swim.","I'm going to swim.","I like swimming."],"nivel":"A1","tags":["cotidiano"],"notaEn":"A learned skill takes «savoir», to know: «je sais nager», I can swim. «Je peux nager» means I'm able or allowed to.","requerTodas":["fr-p008","+nager"],"v":"2872690f"},{"idioma":"fr","id":"fr-u016","tipo":"frase","requer":"fr-p016","fr":"Je ne sais pas où il habite.","en":"I don't know where he lives.","aceitasEn":["i dont know where he lives","i do not know where he lives"],"distratoresEn":["I don't know where he works.","I don't know where he is.","I don't know where he eats.","I don't know where he studies."],"nivel":"A1","tags":["casa"],"notaEn":"«Où», with the accent, is where. In an indirect question the word order stays normal: «où il habite».","requerTodas":["fr-p008","fr-p016"],"v":"5cf93057"},{"idioma":"fr","id":"fr-u017","tipo":"frase","requer":"fr-p009","fr":"Viens ici !","aceitasFr":["Venez ici !","Viens là !"],"en":"Come here!","aceitasEn":["come here","come over here"],"distratoresEn":["Stay here!","Sit here!","Wait here!","Stop here!"],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Tu» imperative: «viens», the present form without «tu». With «vous»: «Venez ici !».","requerTodas":["fr-p009","fr-p048"],"v":"550a83c3"},{"idioma":"fr","id":"fr-u018","tipo":"frase","requer":"fr-p010","fr":"On se voit demain !","aceitasFr":["On se voit demain."],"en":"See you tomorrow!","aceitasEn":["see you tomorrow","well see each other tomorrow","see ya tomorrow"],"distratoresEn":["Talk to you tomorrow!","I'll call you tomorrow!","See you today!","See you later!"],"nivel":"A1","tags":["social"],"notaEn":"«On se voit», literally one sees each other: «on» is the casual we. The present stands in for the future, as in English «see you».","requerTodas":["fr-p010","+demain"],"v":"bc997ce4"},{"idioma":"fr","id":"fr-u019","tipo":"frase","requer":"fr-p010","fr":"Je ne vois rien.","aceitasFr":["Je vois rien."],"en":"I can't see anything.","aceitasEn":["i cant see anything","i cannot see anything","i dont see anything","i see nothing","i can see nothing"],"distratoresEn":["I can't hear anything.","I don't know anything.","I don't want anything.","I'm not eating anything."],"nivel":"A1","tags":["gramática"],"notaEn":"With «rien» (nothing), «pas» drops out: «ne… rien», not… anything. In speech, «Je vois rien».","requerTodas":["fr-p010"],"v":"a4be660f"},{"idioma":"fr","id":"fr-u020","tipo":"frase","requer":"fr-p011","fr":"Je prends le bus.","en":"I take the bus.","aceitasEn":["i take the bus","im taking the bus","i am taking the bus","i catch the bus","i go by bus"],"distratoresEn":["I miss the bus.","I wait for the bus.","I pay for the bus.","I stop the bus."],"nivel":"A1","tags":["cidade","viagem","falso-amigo"],"notaEn":"Transport takes «prendre», to take: «prendre le bus», «prendre le train».","requerTodas":["fr-p011","+le bus"],"v":"5e446580"},{"idioma":"fr","id":"fr-u021","tipo":"frase","requer":"fr-p011","fr":"Je prends ça.","aceitasFr":["Je vais prendre ça.","Je le prends."],"en":"I'll take this.","aceitasEn":["ill take this","i will take this","ill take it","ill take this one"],"distratoresEn":["I'll pay for this.","I'll try this on.","I'll exchange this.","I'll return this."],"nivel":"A1","tags":["compras"],"notaEn":"In a shop, «je prends» means I'll take it. «Ça» is this or that.","requerTodas":["fr-p011"],"v":"33333335"},{"idioma":"fr","id":"fr-u022","tipo":"frase","requer":"fr-p012","fr":"Vous parlez trop vite.","aceitasFr":["Tu parles trop vite."],"en":"You're speaking too fast.","aceitasEn":["youre speaking too fast","you are speaking too fast","you speak too fast","youre talking too fast","you talk too fast","you speak too quickly"],"distratoresEn":["You're walking too fast.","You're eating too fast.","You're reading too fast.","You're driving too fast."],"nivel":"A1","tags":["escola"],"notaEn":"«Trop» means too and goes before the word: «trop vite», too fast.","requerTodas":["fr-p012","+trop","+vite"],"v":"2049a275"},{"idioma":"fr","id":"fr-u023","tipo":"frase","requer":"fr-p012","fr":"Je parle à ma mère.","en":"I'm talking to my mother.","aceitasEn":["im talking to my mother","i am talking to my mother","im talking to my mom","im talking with my mother","im speaking to my mother","i talk to my mother"],"distratoresEn":["I'm calling my mother.","I'm writing to my mother.","I'm waiting for my mother.","I'm listening to my mother."],"nivel":"A1","tags":["família"],"notaEn":"You talk «à» someone: «parler à quelqu'un». «Parler avec» also exists, more for chatting with.","requerTodas":["fr-p012","+la mère"],"v":"7b0e1c55"},{"idioma":"fr","id":"fr-u024","tipo":"frase","requer":"fr-p013","fr":"On mange à midi.","aceitasFr":["Nous mangeons à midi."],"en":"We eat at noon.","aceitasEn":["we eat at noon","we have lunch at noon","we eat at midday","we eat lunch at noon"],"distratoresEn":["We leave at noon.","We arrive at noon.","We sleep at noon.","We drink at noon."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"«On» is the casual we, but it takes the «il» form: «on mange», we eat.","requerTodas":["fr-p013","+midi"],"v":"a0cd2241"},{"idioma":"fr","id":"fr-u025","tipo":"frase","requer":"fr-p013","fr":"Je ne mange pas de viande.","aceitasFr":["Je mange pas de viande."],"en":"I don't eat meat.","aceitasEn":["i dont eat meat","i do not eat meat"],"distratoresEn":["I don't buy meat.","I don't sell meat.","I don't cut meat.","I don't like meat."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"After a negative, «du», «de la» and «des» become «de»: «je mange de la viande», but «je ne mange pas de viande».","requerTodas":["fr-p013","+la viande"],"v":"1e51fac1"},{"idioma":"fr","id":"fr-u026","tipo":"frase","requer":"fr-p014","fr":"Je bois de l'eau.","en":"I drink water.","aceitasEn":["i drink water","im drinking water","i am drinking water","i drink some water"],"distratoresEn":["I buy water.","I ask for water.","I bring water.","I want water."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"Uncountable things take the partitive: «de l'eau», «du pain», «de la viande», where English says some or nothing.","requerTodas":["fr-p014","fr-p026"],"v":"85816d3e"},{"idioma":"fr","id":"fr-u027","tipo":"frase","requer":"fr-p014","fr":"On boit un verre ?","aceitasFr":["On va boire un verre ?","Tu veux boire un verre ?"],"en":"Shall we grab a drink?","aceitasEn":["shall we grab a drink","shall we have a drink","lets have a drink","lets grab a drink","how about a drink","want to grab a drink"],"distratoresEn":["Shall we grab a bite?","Shall we go shopping?","Shall we do something?","Shall we watch a movie?"],"nivel":"A2","tags":["comida","social","expressão"],"notaEn":"Literally «do we drink a glass?»: «boire un verre» means to go for a drink, alcoholic or not.","requerTodas":["fr-p014","+le verre"],"v":"bd47f5e4"},{"idioma":"fr","id":"fr-u028","tipo":"frase","requer":"fr-p015","fr":"J'aime beaucoup le chocolat.","en":"I really like chocolate.","aceitasEn":["i really like chocolate","i like chocolate a lot","i love chocolate","i like chocolate very much"],"distratoresEn":["I don't like chocolate.","I don't really like chocolate.","I really like coffee.","I really like cake."],"nivel":"A1","tags":["comida"],"notaEn":"What you like takes the article: «j'aime le chocolat». «Beaucoup» goes right after the verb.","requerTodas":["fr-p015","+beaucoup","+le chocolat"],"v":"4c820328"},{"idioma":"fr","id":"fr-u029","tipo":"frase","requer":"fr-p015","fr":"Je t'aime.","en":"I love you.","aceitasEn":["i love you"],"distratoresEn":["I'll help you.","I'll wait for you.","I see you.","I hear you."],"nivel":"A1","tags":["família","social"],"notaEn":"With people, plain «aimer» is love. To say you like someone as a friend, add «bien»: «je t'aime bien».","requerTodas":["fr-p015"],"v":"1bf47f32"},{"idioma":"fr","id":"fr-u030","tipo":"frase","requer":"fr-p016","fr":"J'habite à Rio.","en":"I live in Rio.","aceitasEn":["i live in rio","i live in rio de janeiro"],"distratoresEn":["I work in Rio.","I was born in Rio.","I study in Rio.","I'm staying in Rio."],"nivel":"A1","tags":["casa","cidade"],"notaEn":"Cities take «à»: «à Rio», «à Paris». Feminine countries take «en»: «j'habite en France».","requerTodas":["fr-p016"],"v":"741b534c"},{"idioma":"fr","id":"fr-u031","tipo":"frase","requer":"fr-p017","fr":"Elle travaille dans un hôpital.","en":"She works at a hospital.","aceitasEn":["she works at a hospital","she works in a hospital","she works at the hospital"],"distratoresEn":["She lives in a hospital.","She studies at a hospital.","She sleeps in a hospital.","She eats at a hospital."],"nivel":"A1","tags":["trabalho","saúde"],"notaEn":"«Dans» means in, inside. The «h» of «hôpital» is silent: «l'hôpital».","requerTodas":["fr-p017","+l'hôpital"],"v":"76691d35"},{"idioma":"fr","id":"fr-u032","tipo":"frase","requer":"fr-p018","fr":"Attends-moi !","aceitasFr":["Attendez-moi !"],"en":"Wait for me!","aceitasEn":["wait for me","wait up"],"distratoresEn":["Help me!","Understand me!","Listen to me!","Call me!"],"nivel":"A1","tags":["cotidiano","falso-amigo"],"notaEn":"«Attendre» means to wait for, with no preposition. In positive commands the pronoun follows, with a hyphen: «attends-moi».","requerTodas":["fr-p018"],"v":"789d1724"},{"idioma":"fr","id":"fr-u033","tipo":"frase","requer":"fr-p019","fr":"Je travaille tous les jours.","en":"I work every day.","aceitasEn":["i work every day","i work everyday","i work daily"],"distratoresEn":["I work every month.","I work every year.","I work every night.","I work every Sunday."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"«Tous les jours», every day (literally all the days): «tout» agrees, becoming «tous» in the masculine plural.","requerTodas":["fr-p017","+tout","fr-p019"],"v":"656e8aad"},{"idioma":"fr","id":"fr-u034","tipo":"frase","requer":"fr-p020","fr":"Je rentre à la maison.","aceitasFr":["Je rentre chez moi."],"en":"I'm going home.","aceitasEn":["im going home","i am going home","im heading home","im going back home","i go home"],"distratoresEn":["I'm leaving home.","I'm staying home.","I'm cleaning the house.","I'm selling my house."],"nivel":"A1","tags":["casa"],"notaEn":"«Rentrer» is to go back home, or back inside. Being at home is «je suis à la maison».","requerTodas":["+rentrer","fr-p020"],"v":"4f5b5803"},{"idioma":"fr","id":"fr-u035","tipo":"frase","requer":"fr-p021","fr":"Cet homme est mon voisin.","en":"That man is my neighbor.","aceitasEn":["that man is my neighbor","this man is my neighbor","that man is my neighbour"],"distratoresEn":["That boy is my neighbor.","That student is my neighbor.","That doctor is my neighbor.","That waiter is my neighbor."],"nivel":"A1","tags":["família","casa"],"notaEn":"Before a vowel or silent «h», «ce» (this, that) becomes «cet»: «cet homme», «cet ami». Feminine: «cette femme».","requerTodas":["fr-p021","fr-p001","+le voisin"],"v":"ef0a05d9"},{"idioma":"fr","id":"fr-u036","tipo":"frase","requer":"fr-p022","fr":"Sa femme est française.","en":"His wife is French.","aceitasEn":["his wife is french","her wife is french"],"distratoresEn":["His daughter is French.","His sister is French.","His mother is French.","His friend is French."],"nivel":"A1","tags":["família"],"notaEn":"«Sa» agrees with the thing owned, not the owner: «sa femme» is his wife or her wife. Nationality adjectives are lowercase.","requerTodas":["fr-p022","fr-p001","+français"],"v":"ca0c73f9"},{"idioma":"fr","id":"fr-u037","tipo":"frase","requer":"fr-p023","fr":"Les enfants jouent dans la rue.","en":"The children are playing in the street.","aceitasEn":["the children are playing in the street","the kids are playing in the street","the children play in the street","the kids play in the street"],"distratoresEn":["The children are sleeping in the street.","The children are eating in the street.","The children live in the street.","The children are waiting in the street."],"nivel":"A1","tags":["família","cidade"],"notaEn":"«Jouer» is to play, games or instruments: «jouer au foot», «jouer du piano». The «-ent» ending of «jouent» is silent.","requerTodas":["fr-p023","+jouer","fr-p032"],"v":"62ddc370"},{"idioma":"fr","id":"fr-u038","tipo":"frase","requer":"fr-p024","fr":"C'est mon meilleur ami.","en":"He's my best friend.","aceitasEn":["hes my best friend","he is my best friend"],"distratoresEn":["He's my best student.","He's my best neighbor.","He's my new friend.","He's my old friend."],"nivel":"A1","tags":["social"],"notaEn":"«Meilleur» is best or better; feminine «ma meilleure amie» sounds the same.","requerTodas":["fr-p001","+meilleur","fr-p024"],"v":"66d26e89"},{"idioma":"fr","id":"fr-u039","tipo":"frase","requer":"fr-p025","fr":"Je n'ai pas le temps.","aceitasFr":["J'ai pas le temps."],"en":"I don't have time.","aceitasEn":["i dont have time","i do not have time","i have no time","i dont have the time"],"distratoresEn":["I don't have money.","I'm not hungry.","I don't have a car.","I don't have a house."],"nivel":"A1","tags":["cotidiano"],"notaEn":"French uses the article here: «avoir le temps», to have (the) time.","requerTodas":["fr-p002","fr-p025"],"v":"4d2db924"},{"idioma":"fr","id":"fr-u040","tipo":"frase","requer":"fr-p025","fr":"Quel temps fait-il ?","aceitasFr":["Il fait quel temps ?"],"en":"What's the weather like?","aceitasEn":["whats the weather like","what is the weather like","hows the weather","how is the weather"],"distratoresEn":["How much time is left?","What time is it?","How long does it take?","What day is it today?"],"nivel":"A1","tags":["natureza"],"notaEn":"Literally «what weather does it make?». Asking the time is «Quelle heure est-il ?».","requerTodas":["fr-p025","fr-p004"],"v":"2d772968"},{"idioma":"fr","id":"fr-u041","tipo":"frase","requer":"fr-p026","fr":"Un verre d'eau, s'il vous plaît.","en":"A glass of water, please.","aceitasEn":["a glass of water please","glass of water please","a glass of water","could i have a glass of water"],"distratoresEn":["A glass of milk, please.","A glass of wine, please.","A bottle of water, please.","A bowl of soup, please."],"nivel":"A1","tags":["comida"],"notaEn":"«Le verre» is a glass, for drinking or the material. A glass of water: «un verre d'eau», with «de» and no article.","requerTodas":["+le verre","fr-p026"],"v":"59948d5d"},{"idioma":"fr","id":"fr-u042","tipo":"frase","requer":"fr-p027","fr":"J'achète du pain.","en":"I'm buying bread.","aceitasEn":["im buying bread","i am buying bread","i buy bread","i buy some bread","im buying some bread"],"distratoresEn":["I'm buying milk.","I'm buying cheese.","I'm buying rice.","I'm buying coffee."],"nivel":"A1","tags":["comida","compras"],"notaEn":"Bread with no quantity takes the partitive: «du pain», some bread. «Acheter» gets a grave accent before a silent ending: «j'achète», but «nous achetons».","requerTodas":["+acheter","fr-p027"],"v":"78ed37ea"},{"idioma":"fr","id":"fr-u043","tipo":"frase","requer":"fr-p028","fr":"Paris est une grande ville.","en":"Paris is a big city.","aceitasEn":["paris is a big city","paris is a large city","paris is a great city"],"distratoresEn":["Paris is a big village.","Paris is a big island.","Paris is a big square.","Paris is a big street."],"nivel":"A1","tags":["cidade"],"notaEn":"«Grand» usually goes before the noun: «une grande ville». The feminine adds «e», and then the «d» is pronounced.","requerTodas":["fr-p001","fr-p037","fr-p028"],"v":"eea5e1a7"},{"idioma":"fr","id":"fr-u044","tipo":"frase","requer":"fr-p029","fr":"J'aime mon travail.","en":"I like my job.","aceitasEn":["i like my job","i love my job","i like my work","i love my work"],"distratoresEn":["I like my neighborhood.","I like my car.","I like my boss.","I like my room."],"nivel":"A1","tags":["trabalho"],"notaEn":"«Mon travail»: masculine possessive, because «travail» is masculine.","requerTodas":["fr-p015","fr-p029"],"v":"1f7d37ef"},{"idioma":"fr","id":"fr-u045","tipo":"frase","requer":"fr-p030","fr":"Bonne nuit, à demain !","en":"Good night, see you tomorrow!","aceitasEn":["good night see you tomorrow","goodnight see you tomorrow","night see you tomorrow"],"distratoresEn":["Good morning, see you tomorrow!","Good afternoon, see you tomorrow!","Good night, see you later!","Have a good trip, see you tomorrow!"],"nivel":"A1","tags":["social"],"notaEn":"«Bonne nuit» is for bedtime; arriving in the evening, say «Bonsoir».","requerTodas":["fr-p036","fr-p030","+demain"],"v":"c6c1020a"},{"idioma":"fr","id":"fr-u046","tipo":"frase","requer":"fr-p030","fr":"Il travaille la nuit.","en":"He works at night.","aceitasEn":["he works at night","he works nights","he works during the night"],"distratoresEn":["He works during the day.","He works in the afternoon.","He works early.","He works alone."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"With the article and no preposition, «la nuit» means at night, as a habit.","requerTodas":["fr-p017","fr-p030"],"v":"368432ce"},{"idioma":"fr","id":"fr-u047","tipo":"frase","requer":"fr-p031","fr":"Bonne année !","en":"Happy New Year!","aceitasEn":["happy new year"],"distratoresEn":["Happy birthday!","Merry Christmas!","Good luck!","Enjoy your vacation!"],"nivel":"A1","tags":["social","cultura"],"notaEn":"Said from January 1st, and through the whole month. It's «année», not «an», because you wish someone the year as lived.","requerTodas":["fr-p036","fr-p031"],"v":"749578ec"},{"idioma":"fr","id":"fr-u048","tipo":"frase","requer":"fr-p031","fr":"Cette année, je vais en France.","en":"This year I'm going to France.","aceitasEn":["this year im going to france","this year i am going to france","im going to france this year","this year i go to france"],"distratoresEn":["This month I'm going to France.","This summer I'm going to France.","This winter I'm going to France.","This Sunday I'm going to France."],"nivel":"A1","tags":["viagem"],"notaEn":"«Cette» is the feminine of «ce» (this), because «année» is feminine. Feminine countries take «en»: «en France».","requerTodas":["fr-p031","fr-p003"],"v":"1006048d"},{"idioma":"fr","id":"fr-u049","tipo":"frase","requer":"fr-p032","fr":"J'habite dans cette rue.","en":"I live on this street.","aceitasEn":["i live on this street","i live in this street"],"distratoresEn":["I live in this city.","I live in this house.","I live on this square.","I live in this village."],"nivel":"A1","tags":["cidade","casa"],"notaEn":"On a street is «dans la rue». In an address, no preposition or article: «j'habite rue Victor-Hugo».","requerTodas":["fr-p016","fr-p032"],"v":"a02797f6"},{"idioma":"fr","id":"fr-u050","tipo":"frase","requer":"fr-p033","fr":"Je lis un livre.","en":"I'm reading a book.","aceitasEn":["im reading a book","i am reading a book","i read a book"],"distratoresEn":["I'm reading a newspaper.","I'm reading a poem.","I'm reading an email.","I'm reading a note."],"nivel":"A1","tags":["escola"],"notaEn":"«Lire» is to read: je lis, tu lis, il lit, nous lisons. The present also means I'm reading.","requerTodas":["+lire","fr-p033"],"v":"61fa5d56"},{"idioma":"fr","id":"fr-u051","tipo":"frase","requer":"fr-p034","fr":"Ma voiture est en panne.","en":"My car has broken down.","aceitasEn":["my car has broken down","my car broke down","my car is broken down","my car isnt working"],"distratoresEn":["My car has been washed.","My car has been sold.","My car is parked.","My car is dirty."],"nivel":"A2","tags":["cidade","viagem"],"notaEn":"«Ma voiture»: feminine possessive, because «voiture» is feminine. «En panne» works for anything that stops working.","requerTodas":["fr-p034","fr-p001","+la panne"],"v":"b9543d5f"},{"idioma":"fr","id":"fr-u052","tipo":"frase","requer":"fr-p035","fr":"Je n'ai pas d'argent.","aceitasFr":["J'ai pas d'argent."],"en":"I don't have any money.","aceitasEn":["i dont have any money","i dont have money","i have no money","i do not have any money"],"distratoresEn":["I don't have any time.","I don't have any change.","I don't have a card.","I don't have any work."],"nivel":"A1","tags":["compras","economia"],"notaEn":"After a negative, just «de»: «pas d'argent». In the positive, the partitive: «j'ai de l'argent», I have (some) money.","requerTodas":["fr-p002","fr-p035"],"v":"ee886767"},{"idioma":"fr","id":"fr-u053","tipo":"frase","requer":"fr-p036","fr":"C'est très bon !","en":"It's really good!","aceitasEn":["its really good","its very good","it is very good","its delicious","its so good","its really tasty"],"distratoresEn":["It's really salty!","It's really hot!","It's really sweet!","It's really expensive!"],"nivel":"A1","tags":["comida"],"notaEn":"For food, «bon» means tasty. Hot, as in temperature, is «chaud».","requerTodas":["fr-p001","fr-p043","fr-p036"],"v":"20734602"},{"idioma":"fr","id":"fr-u054","tipo":"frase","requer":"fr-p037","fr":"Mon frère est très grand.","en":"My brother is very tall.","aceitasEn":["my brother is very tall","my brother is really tall","my brother is very big"],"distratoresEn":["My brother is very short.","My brother is very young.","My brother is very thin.","My brother is very strong."],"nivel":"A1","tags":["família"],"notaEn":"For people, «grand» is tall and «petit» is short.","requerTodas":["+le frère","fr-p001","fr-p043","fr-p037"],"v":"55a9ee26"},{"idioma":"fr","id":"fr-u055","tipo":"frase","requer":"fr-p038","fr":"Mon appartement est petit.","en":"My apartment is small.","aceitasEn":["my apartment is small","my flat is small","my apartment is little"],"distratoresEn":["My apartment is new.","My apartment is expensive.","My apartment is old.","My apartment is pretty."],"nivel":"A1","tags":["casa"],"notaEn":"«Petit» can follow «être», as here, or go before the noun: «un petit appartement».","requerTodas":["+l'appartement","fr-p001","fr-p038"],"v":"ca792e7d"},{"idioma":"fr","id":"fr-u056","tipo":"frase","requer":"fr-p039","fr":"J'ai une nouvelle voiture.","en":"I have a new car.","aceitasEn":["i have a new car","ive got a new car","i got a new car"],"distratoresEn":["I have an old car.","I have an expensive car.","I have a nice car.","I have a small car."],"nivel":"A1","tags":["cidade"],"notaEn":"«Nouvelle» agrees with «voiture» and goes before it. «Une voiture neuve» is a brand-new car, never used.","requerTodas":["fr-p002","fr-p039","fr-p034"],"v":"0711218d"},{"idioma":"fr","id":"fr-u057","tipo":"frase","requer":"fr-p040","fr":"Quelle belle maison !","en":"What a beautiful house!","aceitasEn":["what a beautiful house","what a lovely house","what a pretty house"],"distratoresEn":["What a big house!","What an old house!","What a small house!","What an expensive house!"],"nivel":"A1","tags":["casa"],"notaEn":"«Belle» is the feminine of «beau». Exclamatory «quel» (what a) agrees too: «quelle maison», «quel livre».","requerTodas":["fr-p040","fr-p020"],"v":"9657bf10"},{"idioma":"fr","id":"fr-u058","tipo":"frase","requer":"fr-p041","fr":"C'est un vieil ami.","en":"He's an old friend.","aceitasEn":["hes an old friend","he is an old friend","its an old friend"],"distratoresEn":["He's a new friend.","He's a good friend.","He's a great friend.","He's a false friend."],"nivel":"A2","tags":["social"],"notaEn":"Before a vowel, «vieux» becomes «vieil»: «un vieil ami», «un vieil homme». It sounds like «vieille».","requerTodas":["fr-p001","fr-p041","fr-p024"],"v":"cd54833a"},{"idioma":"fr","id":"fr-u059","tipo":"frase","requer":"fr-p042","fr":"Je suis content de te voir.","aceitasFr":["Je suis contente de te voir."],"en":"I'm glad to see you.","aceitasEn":["im glad to see you","im happy to see you","i am glad to see you","i am happy to see you","good to see you","nice to see you","its good to see you"],"distratoresEn":["I'm sad to see you.","I'm glad to hear from you.","I'm glad to help you.","I'm glad to meet you."],"nivel":"A1","tags":["social"],"notaEn":"«Content de» + infinitive: glad to. A woman says «contente».","requerTodas":["fr-p001","fr-p042","fr-p010"],"v":"c7f09ccf"},{"idioma":"fr","id":"fr-u060","tipo":"frase","requer":"fr-p043","fr":"Il fait très froid.","en":"It's very cold.","aceitasEn":["its very cold","it is very cold","its really cold","its freezing"],"distratoresEn":["It's very hot.","It's a bit cold.","It's kind of cold.","It's very humid."],"nivel":"A1","tags":["natureza"],"notaEn":"«Froid» is an adjective here, so it takes «très»: «il fait très froid».","requerTodas":["fr-p004","fr-p043","+froid"],"v":"498777fd"},{"idioma":"fr","id":"fr-u061","tipo":"frase","requer":"fr-p044","fr":"Tu parles très bien français !","aceitasFr":["Vous parlez très bien français !","Tu parles très bien le français !"],"en":"You speak French very well!","aceitasEn":["you speak french very well","you speak very good french","your french is very good","you speak french really well"],"distratoresEn":["You speak French very badly!","You speak French very fast!","You speak French very loudly!","You speak very little French!"],"nivel":"A1","tags":["escola"],"notaEn":"«Bien» modifies the verb. «Bon» is the adjective: «un bon livre».","requerTodas":["fr-p012","fr-p043","fr-p044","+le français"],"v":"35a6d15e"},{"idioma":"fr","id":"fr-u062","tipo":"frase","requer":"fr-p045","fr":"Elle parle aussi anglais.","aceitasFr":["Elle parle anglais aussi.","Elle parle aussi l'anglais."],"en":"She also speaks English.","aceitasEn":["she also speaks english","she speaks english too","she speaks english as well"],"distratoresEn":["She only speaks English.","She still speaks English.","She already speaks English.","She doesn't speak English."],"nivel":"A1","tags":["escola"],"notaEn":"«Aussi» comes after the verb: «elle parle aussi anglais». With a pronoun alone: «moi aussi», me too.","requerTodas":["fr-p045","fr-p012","+l'anglais"],"v":"b6ae8663"},{"idioma":"fr","id":"fr-u063","tipo":"frase","requer":"fr-p046","fr":"Il habite toujours ici.","en":"He still lives here.","aceitasEn":["he still lives here"],"distratoresEn":["He already lives here.","He doesn't live here anymore.","He almost lives here.","He only lives here."],"nivel":"A2","tags":["casa"],"notaEn":"Here «toujours» means still. The opposite is «ne… plus»: «il n'habite plus ici», he doesn't live here anymore.","requerTodas":["fr-p016","fr-p046","fr-p048"],"v":"db312dc7"},{"idioma":"fr","id":"fr-u064","tipo":"frase","requer":"fr-p047","fr":"Je dois partir maintenant.","en":"I have to leave now.","aceitasEn":["i have to leave now","i have to go now","i need to go now","i need to leave now","i must go now","i must leave now","i gotta go now"],"distratoresEn":["I have to leave tomorrow.","I have to leave soon.","I have to leave early.","I have to leave later."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Devoir» is to have to, must. «Partir» is to leave, go away.","requerTodas":["+devoir","+partir","fr-p047"],"v":"6bc31c25"},{"idioma":"fr","id":"fr-u065","tipo":"frase","requer":"fr-p048","fr":"Ici, on parle français.","en":"French is spoken here.","aceitasEn":["french is spoken here","we speak french here","here we speak french","here people speak french"],"distratoresEn":["French is spoken there.","French is spoken over there.","French is spoken like this.","French is spoken nearby."],"nivel":"A1","tags":["viagem"],"notaEn":"«On» works as the impersonal subject: «on parle», one speaks, is spoken. After «parler», the language needs no article.","requerTodas":["fr-p048","fr-p012","+le français"],"v":"30e84cdd"},{"idioma":"fr","id":"fr-u066","tipo":"frase","requer":"fr-p049","fr":"Aujourd'hui, c'est lundi.","aceitasFr":["Aujourd'hui, on est lundi.","On est lundi aujourd'hui."],"en":"Today is Monday.","aceitasEn":["today is monday","its monday today","it is monday today","today its monday"],"distratoresEn":["Yesterday was Monday.","Tomorrow is Monday.","Today is Tuesday.","Today is Sunday."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Days of the week are lowercase in French and take no article here: «c'est lundi». People also say «on est lundi».","requerTodas":["fr-p049","fr-p001","+lundi"],"v":"aacfcbb0"},{"idioma":"fr","id":"fr-u067","tipo":"frase","requer":"fr-p050","fr":"J'ai déjà mangé.","en":"I've already eaten.","aceitasEn":["ive already eaten","i have already eaten","i already ate","ive eaten already"],"distratoresEn":["I haven't eaten yet.","I'm about to eat.","I've never eaten.","I ate very little."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"«Déjà» sits between the helper verb and the participle: «j'ai déjà mangé».","requerTodas":["fr-p002","fr-p050","fr-p013"],"v":"3cf8da8a"},{"idioma":"fr","id":"fr-v001","tipo":"frase","fr":"Je suis en retard.","en":"I'm late.","aceitasEn":["im late","i am late","im running late","i am running late"],"distratoresEn":["I was late.","I've been late.","I'll be late.","I would be late."],"formasFr":{"J'étais en retard":"imperfect","J'ai été en retard":"passé composé","Je serai en retard":"future","Je serais en retard":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«En retard» doesn't change for gender. Present of «être»: je suis, tu es, il est, nous sommes, vous êtes, ils sont.","requerTodas":["fr-p001","+le retard"],"v":"32b657be"},{"idioma":"fr","id":"fr-v002","tipo":"frase","fr":"Ils ont faim.","aceitasFr":["Elles ont faim."],"en":"They're hungry.","aceitasEn":["theyre hungry","they are hungry"],"distratoresEn":["They were hungry.","They got hungry.","They'll be hungry.","They'd be hungry."],"formasFr":{"Ils avaient faim":"imperfect","Ils ont eu faim":"passé composé","Ils auront faim":"future","Ils auraient faim":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«Ils ont» (they have) links with a «z» sound: «eel-ZON». «Ils sont» (they are) has an «s» sound: watch the difference.","requerTodas":["fr-p002","+la faim"],"v":"53af2e05"},{"idioma":"fr","id":"fr-v003","tipo":"frase","fr":"Je vais à la plage.","en":"I'm going to the beach.","aceitasEn":["im going to the beach","i am going to the beach","i go to the beach"],"distratoresEn":["I was going to the beach.","I went to the beach.","I'll go to the beach.","I would go to the beach."],"formasFr":{"J'allais à la plage":"imperfect","Je suis allé à la plage":"passé composé","J'irai à la plage":"future","J'irais à la plage":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","viagem"],"notaEn":"Present of «aller»: je vais, tu vas, il va, nous allons, vous allez, ils vont. The future switches stems: «j'irai».","requerTodas":["fr-p003","+la plage"],"v":"0c321ca5"},{"idioma":"fr","id":"fr-v004","tipo":"frase","fr":"Il fait la cuisine.","en":"He's cooking.","aceitasEn":["hes cooking","he is cooking","he cooks","he does the cooking"],"distratoresEn":["He was cooking.","He cooked.","He'll cook.","He would cook."],"formasFr":{"Il faisait la cuisine":"imperfect","Il a fait la cuisine":"passé composé","Il fera la cuisine":"future","Il ferait la cuisine":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","comida"],"notaEn":"«Faire la cuisine» is to cook; «la cuisine» is also the kitchen. Future of «faire»: «il fera».","requerTodas":["fr-p004","+la cuisine"],"v":"1e1d4ca0"},{"idioma":"fr","id":"fr-v005","tipo":"frase","fr":"Ils prennent le train.","aceitasFr":["Elles prennent le train."],"en":"They take the train.","aceitasEn":["they take the train","theyre taking the train","they are taking the train","they go by train"],"distratoresEn":["They used to take the train.","They took the train.","They'll take the train.","They would take the train."],"formasFr":{"Ils prenaient le train":"imperfect","Ils ont pris le train":"passé composé","Ils prendront le train":"future","Ils prendraient le train":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","viagem"],"notaEn":"Present of «prendre»: je prends, nous prenons, ils prennent (double «n»). Past participle: «pris».","requerTodas":["fr-p011","+le train"],"v":"134296ed"},{"idioma":"fr","id":"fr-v006","tipo":"frase","fr":"Il ne peut pas venir.","aceitasFr":["Il peut pas venir."],"en":"He can't come.","aceitasEn":["he cant come","he cannot come","he is not able to come","he isnt able to come"],"distratoresEn":["He couldn't come.","He wasn't able to come.","He won't be able to come.","He wouldn't be able to come."],"formasFr":{"Il ne pouvait pas venir":"imperfect","Il n'a pas pu venir":"passé composé","Il ne pourra pas venir":"future","Il ne pourrait pas venir":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"The future and conditional of «pouvoir» have a double «r»: «il pourra», «il pourrait». Past participle: «pu».","requerTodas":["fr-p006","fr-p009"],"v":"4db35ee9"},{"idioma":"fr","id":"fr-v007","tipo":"frase","fr":"Elle veut un chien.","en":"She wants a dog.","aceitasEn":["she wants a dog"],"distratoresEn":["She used to want a dog.","She wanted a dog.","She'll want a dog.","She would like a dog."],"formasFr":{"Elle voulait un chien":"imperfect","Elle a voulu un chien":"passé composé","Elle voudra un chien":"future","Elle voudrait un chien":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","animais"],"notaEn":"Present of «vouloir»: je veux, tu veux, il veut, nous voulons, ils veulent. The conditional, «elle voudrait», is would like.","requerTodas":["fr-p007","+le chien"],"v":"267773ab"},{"idioma":"fr","id":"fr-v008","tipo":"frase","fr":"Je sais la réponse.","aceitasFr":["Je connais la réponse."],"en":"I know the answer.","aceitasEn":["i know the answer"],"distratoresEn":["I knew the answer.","I found out the answer.","I'll know the answer.","I would know the answer."],"formasFr":{"Je savais la réponse":"imperfect","J'ai su la réponse":"passé composé","Je saurai la réponse":"future","Je saurais la réponse":"conditional"},"nivel":"A2","tags":["conjugação","presente","irregular"],"notaEn":"Irregular future: «je saurai». In the passé composé, «j'ai su» means I found out.","requerTodas":["fr-p008","+la réponse"],"v":"3804a2c2"},{"idioma":"fr","id":"fr-v009","tipo":"frase","fr":"Il vient avec nous.","en":"He's coming with us.","aceitasEn":["hes coming with us","he is coming with us","he comes with us"],"distratoresEn":["He was coming with us.","He came with us.","He'll come with us.","He would come with us."],"formasFr":{"Il venait avec nous":"imperfect","Il est venu avec nous":"passé composé","Il viendra avec nous":"future","Il viendrait avec nous":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«Venir» forms the passé composé with «être»: «il est venu». The future adds a «d»: «il viendra».","requerTodas":["fr-p009"],"v":"77b9eb82"},{"idioma":"fr","id":"fr-v010","tipo":"frase","fr":"Il m'a dit non.","en":"He told me no.","aceitasEn":["he told me no","he said no to me","he said no"],"distratoresEn":["He tells me no.","He used to tell me no.","He'll tell me no.","He would tell me no."],"formasFr":{"Il me dit non":"present","Il me disait non":"imperfect","Il me dira non":"future","Il me dirait non":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"The past participle of «dire» is «dit». The pronoun goes before the helper verb: «il m'a dit», he told me.","requerTodas":["fr-p005"],"v":"53201d87"},{"idioma":"fr","id":"fr-v011","tipo":"frase","fr":"Je vois la mer.","en":"I can see the sea.","aceitasEn":["i can see the sea","i see the sea","i can see the ocean","i see the ocean"],"distratoresEn":["I could see the sea.","I saw the sea.","I'll see the sea.","I would see the sea."],"formasFr":{"Je voyais la mer":"imperfect","J'ai vu la mer":"passé composé","Je verrai la mer":"future","Je verrais la mer":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","natureza"],"notaEn":"«La mer» is feminine. The future of «voir» has a double «r»: «je verrai». Past participle: «vu».","requerTodas":["fr-p010","+la mer"],"v":"4d9beb5d"},{"idioma":"fr","id":"fr-v012","tipo":"frase","fr":"Il boit du vin.","en":"He drinks wine.","aceitasEn":["he drinks wine","hes drinking wine","he is drinking wine"],"distratoresEn":["He used to drink wine.","He drank wine.","He'll drink wine.","He would drink wine."],"formasFr":{"Il buvait du vin":"imperfect","Il a bu du vin":"passé composé","Il boira du vin":"future","Il boirait du vin":"conditional"},"nivel":"A2","tags":["conjugação","presente","irregular","comida"],"notaEn":"«Boire» changes stem in the plural and the imperfect: «nous buvons», «il buvait». Past participle: «bu».","requerTodas":["fr-p014","+le vin"],"v":"29315c51"},{"idioma":"fr","id":"fr-v013","tipo":"frase","fr":"Elle parle trois langues.","en":"She speaks three languages.","aceitasEn":["she speaks three languages","she speaks 3 languages"],"distratoresEn":["She used to speak three languages.","She spoke three languages.","She'll speak three languages.","She would speak three languages."],"formasFr":{"Elle parlait trois langues":"imperfect","Elle a parlé trois langues":"passé composé","Elle parlera trois langues":"future","Elle parlerait trois langues":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular"],"notaEn":"The regular «-er» pattern: future and conditional are built on the whole infinitive, «parler-a», «parler-ait».","requerTodas":["fr-p012","+trois","+la langue"],"v":"66b835c2"},{"idioma":"fr","id":"fr-v014","tipo":"frase","fr":"J'ai mangé une pomme.","en":"I ate an apple.","aceitasEn":["i ate an apple","ive eaten an apple","i have eaten an apple","i had an apple"],"distratoresEn":["I'm eating an apple.","I was eating an apple.","I'm going to eat an apple.","I'll eat an apple."],"formasFr":{"Je mange une pomme":"present","Je mangeais une pomme":"imperfect","Je vais manger une pomme":"near future","Je mangerai une pomme":"future"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"The everyday past is the passé composé: «avoir» + participle, used for both I ate and I have eaten. In «-er» verbs the participle ends in «-é».","requerTodas":["fr-p013","+la pomme"],"v":"b8da37f8"},{"idioma":"fr","id":"fr-v015","tipo":"frase","fr":"Nous sommes allés au cinéma.","aceitasFr":["Nous sommes allées au cinéma.","On est allés au cinéma."],"en":"We went to the movies.","aceitasEn":["we went to the movies","we went to the cinema","we went to see a movie"],"distratoresEn":["We're going to the movies.","We used to go to the movies.","We'll go to the movies.","We would go to the movies."],"formasFr":{"Nous allons au cinéma":"present","Nous allions au cinéma":"imperfect","Nous irons au cinéma":"future","Nous irions au cinéma":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cultura"],"notaEn":"Verbs of motion (aller, venir, partir, arriver…) take «être» in the passé composé, and the participle agrees: «nous sommes allés», «elles sont allées».","requerTodas":["fr-p001","fr-p003","+le cinéma"],"v":"901332c6"},{"idioma":"fr","id":"fr-v016","tipo":"frase","fr":"Elle est partie.","en":"She left.","aceitasEn":["she left","she has left","she went away","she has gone"],"distratoresEn":["She's leaving.","She was leaving.","She's going to leave.","She'll leave."],"formasFr":{"Elle part":"present","Elle partait":"imperfect","Elle va partir":"near future","Elle partira":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular"],"notaEn":"«Partir» takes «être» in the passé composé, and the participle agrees with her: «elle est partie».","requerTodas":["fr-p001","+partir"],"v":"f2bb4f04"},{"idioma":"fr","id":"fr-v017","tipo":"frase","fr":"Je travaillais à Paris.","en":"I used to work in Paris.","aceitasEn":["i used to work in paris","i was working in paris"],"distratoresEn":["I work in Paris.","I worked in Paris.","I'll work in Paris.","I would work in Paris."],"formasFr":{"Je travaille à Paris":"present","J'ai travaillé à Paris":"passé composé","Je travaillerai à Paris":"future","Je travaillerais à Paris":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","regular","trabalho"],"notaEn":"The imperfect tells what used to happen. Its endings are the same for every verb: -ais, -ais, -ait, -ions, -iez, -aient.","requerTodas":["fr-p017"],"v":"ca1acc28"},{"idioma":"fr","id":"fr-v018","tipo":"frase","fr":"Il faisait froid.","en":"It was cold.","aceitasEn":["it was cold"],"distratoresEn":["It's cold.","It's been cold.","It'll be cold.","It would be cold."],"formasFr":{"Il fait froid":"present","Il a fait froid":"passé composé","Il fera froid":"future","Il ferait froid":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","natureza"],"notaEn":"The imperfect describes the background: what the weather was like. The passé composé, «il a fait froid», reports a closed period.","requerTodas":["fr-p004","+froid"],"v":"11f105a0"},{"idioma":"fr","id":"fr-v019","tipo":"frase","fr":"On va manger au restaurant.","aceitasFr":["Nous allons manger au restaurant."],"en":"We're going to eat at the restaurant.","aceitasEn":["we are going to eat at the restaurant","were going to eat at the restaurant","were going to eat at a restaurant","we are going to eat at a restaurant"],"distratoresEn":["We eat at the restaurant.","We ate at the restaurant.","We used to eat at the restaurant.","We would eat at the restaurant."],"formasFr":{"On mange au restaurant":"present","On a mangé au restaurant":"passé composé","On mangeait au restaurant":"imperfect","On mangerait au restaurant":"conditional"},"nivel":"A1","tags":["conjugação","futuro","comida"],"notaEn":"The near future is «aller» + infinitive, just like going to: «on va manger». It's the most common future in speech.","requerTodas":["fr-p003","fr-p013","+le restaurant"],"v":"4ddf5afc"},{"idioma":"fr","id":"fr-v020","tipo":"frase","fr":"Tu verras.","en":"You'll see.","aceitasEn":["youll see","you will see","you are going to see"],"distratoresEn":["You see.","You saw.","You used to see.","You would see."],"formasFr":{"Tu vois":"present","Tu as vu":"passé composé","Tu voyais":"imperfect","Tu verrais":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"The simple future adds the endings of «avoir» to the infinitive: «tu parleras». Some verbs change stem: «tu verras», «tu seras», «tu auras», «tu iras».","requerTodas":["fr-p010"],"v":"79a0aaf4"},{"idioma":"fr","id":"fr-v021","tipo":"frase","fr":"Ce serait génial !","en":"That would be great!","aceitasEn":["that would be great","it would be great","thatd be great","that would be awesome"],"distratoresEn":["That's great!","That was great!","It's been great!","That'll be great!"],"formasFr":{"C'est génial":"present","C'était génial":"imperfect","Ça a été génial":"passé composé","Ce sera génial":"future"},"nivel":"A2","tags":["conjugação","condicional","irregular"],"notaEn":"The conditional joins the future stem and the imperfect endings: «ser-» + «-ait» = «serait».","requerTodas":["fr-p001","+génial"],"v":"4b22e78a"},{"idioma":"fr","id":"fr-v022","tipo":"frase","fr":"Tu as vu ce film ?","aceitasFr":["Vous avez vu ce film ?"],"en":"Did you see this movie?","aceitasEn":["did you see this movie","have you seen this movie","did you see that movie","have you seen this film","did you watch this movie"],"distratoresEn":["Are you watching this movie?","Did you use to watch this movie?","Are you going to see this movie?","Will you see this movie?"],"formasFr":{"Tu vois ce film":"present","Tu voyais ce film":"imperfect","Tu vas voir ce film":"near future","Tu verras ce film":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cultura"],"notaEn":"Irregular participle of «voir»: «vu». «Ce film»: «ce» means this or that.","requerTodas":["fr-p002","fr-p010","+le film"],"v":"9a1dc044"},{"idioma":"fr","id":"fr-v023","tipo":"frase","fr":"J'ai pris le métro.","en":"I took the subway.","aceitasEn":["i took the subway","i took the metro","ive taken the subway","i have taken the subway","i took the underground"],"distratoresEn":["I take the subway.","I used to take the subway.","I'm going to take the subway.","I'll take the subway."],"formasFr":{"Je prends le métro":"present","Je prenais le métro":"imperfect","Je vais prendre le métro":"near future","Je prendrai le métro":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cidade"],"notaEn":"Irregular participle of «prendre»: «pris», silent «s». Same in «apprendre», «appris», and «comprendre», «compris».","requerTodas":["fr-p002","fr-p011","+le métro"],"v":"e24d550c"},{"idioma":"fr","id":"fr-v024","tipo":"frase","fr":"J'ai eu peur.","en":"I got scared.","aceitasEn":["i got scared","i was scared","i was afraid","i got frightened"],"distratoresEn":["I'm scared.","I used to be scared.","I'll be scared.","I would be scared."],"formasFr":{"J'ai peur":"present","J'avais peur":"imperfect","J'aurai peur":"future","J'aurais peur":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"Fear is something you have: «avoir peur». The participle of «avoir» is «eu», pronounced like the «u» in «tu».","requerTodas":["fr-p002","+la peur"],"v":"a8be7ff7"}]};
